import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { create_list_edit_delete_category } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogTicketTags: Boolean
  },
  mixins: [get_all_org_users],
  components: {
    SnackBar
  },
  data: () => ({
    category: "",
    agents: [],
    prefix: "",
    assignment_mode: "CLAIM_TICKET",
    moderator: "",
    loading: false,
    SnackBarComponent: {},
    TicketAssignmentModes: [{
      title: "Claim",
      value: "CLAIM_TICKET"
    }, {
      title: "Round Robin",
      value: "ROUND_ROBIN"
    }, {
      title: "Load Sharing",
      value: "LOAD_SHARING"
    }, {
      title: "Moderator",
      value: "MODERATOR"
    }]
  }),
  watch: {
    DialogTicketTags(val) {
      if (!val) {
        this.$refs.form.reset();
      } else {
        return this.fetchTicketCategoryData();
      }
    }
  },
  computed: {
    userList() {
      return this.orgUsers.filter(user => user.user_status === "ACTIVE").sort((a, b) => a.user_email_id.localeCompare(b.user_email_id)).map(user => ({
        title: user.user_email_id,
        value: user.user_email_id
      }));
    },
    moderatorList() {
      return this.agents.length ? this.userList.filter(user => this.agents.some(agent => agent.value === user.value)) : [];
    },
    iconForSelectWatchers() {
      if (this.selectAllAgents) return "mdi-close-box";
      if (this.selectSomeAgents) return "mdi-minus-box";
      return "mdi-checkbox-blank-outline";
    },
    selectAllAgents() {
      if (this.agents) {
        return this.agents.length === this.userList.length;
      } else return false;
    },
    selectSomeAgents() {
      if (this.agents) {
        return this.agents.length > 0 && !this.selectAllAgents;
      } else return false;
    }
  },
  methods: {
    async fetchTicketCategoryData() {
      await this.get_all_org_users();
    },
    async ValidateForm() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.AddCategory();
      }
    },
    async AddCategory() {
      this.loading = true;
      try {
        const agentEmails = this.agents.map(user => user.value);
        const result = await API.graphql(graphqlOperation(create_list_edit_delete_category, {
          input: {
            action_type: "CREATE",
            category_name: this.category,
            auto_assign_group: agentEmails,
            prefix_name: this.prefix,
            ticket_distribution: this.assignment_mode,
            moderator_email: this.moderator || null
          }
        }));
        let resultObj = JSON.parse(result.data.create_list_edit_delete_category);
        if (resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: "☑️ " + resultObj.Message
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "❎ " + resultObj.Message
          };
        }
        this.loading = false;
        this.DialogTicketTagsEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "❎ Failed to create category, please try again"
        };
      }
      this.loading = false;
    },
    DialogTicketTagsEmit(Toggle) {
      this.$emit("clicked", Toggle);
    },
    toggleForSelectWatchers() {
      if (this.selectAllAgents) {
        this.agents = [];
      } else {
        this.agents = [...this.userList];
      }
    }
  }
};
